-- Additive V7: encrypted originals, sanitized row ledger, mandatory independent DR.
create table private.v7_inventory_backup(id uuid primary key default gen_random_uuid(),table_name text not null,row_id uuid,snapshot jsonb not null,created_at timestamptz not null default now());
alter table private.v7_inventory_backup enable row level security;create policy service_only on private.v7_inventory_backup for all to service_role using(true) with check(true);revoke all on private.v7_inventory_backup from public,anon,authenticated;grant all on private.v7_inventory_backup to service_role;
insert into private.v7_inventory_backup(table_name,row_id,snapshot) select 'websites',id,to_jsonb(w) from public.websites w union all select 'website_qualifications',website_id,to_jsonb(q) from public.website_qualifications q union all select 'settings',tenant_id,to_jsonb(s) from public.settings s;
alter table public.workbook_imports add column source_handling text not null default 'private_plaintext_v6',add column source_options jsonb not null default '{}',add column source_summary jsonb not null default '{}';
alter table public.website_qualifications add column discovery_evidence jsonb not null default '{}';
create table private.workbook_envelopes(tenant_id uuid not null references public.tenants(id),owner_id uuid not null references public.profiles(id),source_sha256 text not null check(source_sha256 ~ '^[a-f0-9]{64}$'),storage_path text not null,secret_id uuid not null,created_at timestamptz not null default now(),primary key(tenant_id,source_sha256));
create index workbook_envelopes_owner_idx on private.workbook_envelopes(owner_id);alter table private.workbook_envelopes enable row level security;create policy service_only on private.workbook_envelopes for all to service_role using(true) with check(true);revoke all on private.workbook_envelopes from public,anon,authenticated;grant all on private.workbook_envelopes to service_role;
update storage.buckets set file_size_limit=20971584 where id='workbook-sources';
create function private.store_workbook_envelope(p_actor uuid,p_sha text,p_path text,p_key text,p_iv text) returns jsonb language plpgsql security definer set search_path='' as $$ declare a public.profiles;e private.workbook_envelopes;s uuid;begin
 select * into a from public.profiles where id=p_actor and active;if not private.actor_permission(p_actor,'websites.create') or p_sha !~ '^[a-f0-9]{64}$' or p_path not like a.tenant_id::text||'/'||a.id::text||'/'||p_sha||'-%' or length(p_key)<>44 or length(p_iv)<>16 then raise exception 'Invalid encrypted workbook envelope';end if;
 perform 1 from public.tenants where id=a.tenant_id for update;select * into e from private.workbook_envelopes where tenant_id=a.tenant_id and source_sha256=p_sha;if e.source_sha256 is not null then if e.owner_id<>a.id and not private.actor_permission(a.id,'websites.read_all') then raise exception 'Source is managed by another employee';end if;return jsonb_build_object('storage_path',e.storage_path);end if;
 select vault.create_secret(jsonb_build_object('key',p_key,'iv',p_iv)::text,'workbook-'||a.tenant_id||'-'||p_sha) into s;insert into private.workbook_envelopes values(a.tenant_id,a.id,p_sha,p_path,s,now());return jsonb_build_object('storage_path',p_path);
end $$;
create function private.read_workbook_envelope(p_actor uuid,p_sha text) returns jsonb language sql stable security definer set search_path='' as $$ select v.decrypted_secret::jsonb||jsonb_build_object('storage_path',e.storage_path) from public.profiles a join private.workbook_envelopes e on e.tenant_id=a.tenant_id join vault.decrypted_secrets v on v.id=e.secret_id where a.id=p_actor and private.actor_permission(a.id,'websites.create') and (e.owner_id=a.id or private.actor_permission(a.id,'websites.read_all')) and e.source_sha256=p_sha $$;
create function public.store_workbook_envelope(p_actor uuid,p_sha text,p_path text,p_key text,p_iv text) returns jsonb language sql set search_path='' as $$ select private.store_workbook_envelope(p_actor,p_sha,p_path,p_key,p_iv) $$;
create function public.read_workbook_envelope(p_actor uuid,p_sha text) returns jsonb language sql stable set search_path='' as $$ select private.read_workbook_envelope(p_actor,p_sha) $$;
revoke all on function private.store_workbook_envelope(uuid,text,text,text,text),private.read_workbook_envelope(uuid,text) from public,anon,authenticated;grant execute on function private.store_workbook_envelope(uuid,text,text,text,text),private.read_workbook_envelope(uuid,text) to service_role;
revoke all on function public.store_workbook_envelope(uuid,text,text,text,text),public.read_workbook_envelope(uuid,text) from public,anon,authenticated;grant execute on function public.store_workbook_envelope(uuid,text,text,text,text),public.read_workbook_envelope(uuid,text) to service_role;
-- Permit physical row 1 in headerless sources; existing nonzero header contracts remain valid.
do $$ declare d text;begin d:=pg_get_functiondef('public.start_workbook_import(uuid,text,text,text,jsonb,jsonb)'::regprocedure);if position('(s->>''header_row'')::integer<1' in d)=0 then raise exception 'Inspect workbook manifest guard before changing it';end if;execute replace(d,'(s->>''header_row'')::integer<1','(s->>''header_row'')::integer<0');end $$;
update public.settings set qualification_policy=qualification_policy||'{"minimum_dr":30}',quality_filters=quality_filters||'{"minimum_dr":30}',publisher_filters=publisher_filters||'{"minimum_dr":30}';
alter function private.website_state(uuid) rename to website_state_v6;
create function private.website_state(p_website uuid) returns jsonb language plpgsql stable set search_path='' as $$ declare s jsonb;dr numeric;minimum_dr numeric;seo_ok boolean;q public.website_qualifications;begin
 s:=private.website_state_v6(p_website);if s is null then return null;end if;select greatest(30,coalesce((x.qualification_policy->>'minimum_dr')::numeric,30)) into minimum_dr from public.websites w join public.settings x on x.tenant_id=w.tenant_id where w.id=p_website;dr:=private.fresh_website_metric(p_website,'domain_rating','ahrefs');select * into q from public.website_qualifications where website_id=p_website;
 s:=s||jsonb_build_object('domain_rating',dr,'discovery',q.discovery_evidence);
 if dr is not null and dr<minimum_dr then s:=s||jsonb_build_object('auto_ready',false,'group','rejected','quality_status',case when s->>'quality_status' like 'rejected_%' then 'rejected_multiple_metrics' else 'rejected_low_dr' end,'publishing_status','rejected_seo_criteria','reason','Verified Ahrefs DR is below the required minimum of at least 30.');
 elsif dr is null then s:=s||jsonb_build_object('auto_ready',false);if s->>'quality_status' not like 'rejected_%' then s:=s||jsonb_build_object('quality_status','pending_seo_verification','group',case when s->>'group'='rejected' then 'rejected' else 'pending_verification' end,'reason',case when (s->>'spreadsheet_source')::boolean then 'Current licensed Moz DA, Ahrefs DR and Moz Spam Score are required. Spreadsheet scores do not qualify.' else s->>'reason' end);end if;
 else seo_ok:=(s->>'quality_status'='metrics_verified') and (s->>'spreadsheet_source')::boolean and s->>'reachability_status'='reachable' and q.reachability_checked_at>now()-interval '7 days' and q.editorial_review='approved' and q.reviewed_content_sha=q.reachability_evidence->>'content_sha' and q.reviewed_at>now()-interval '30 days' and not coalesce((s->>'label_mismatch')::boolean,false);if seo_ok and not (s->>'auto_ready')::boolean and s->>'group'<>'qualified_prospect' then s:=s||jsonb_build_object('group','seo_qualified_connection_pending');end if;
 end if;return s;
end $$;
create or replace function private.website_is_ready(p_website uuid) returns boolean language sql stable set search_path='' as $$ select coalesce((private.website_state(p_website)->>'auto_ready')::boolean,false) $$;
revoke all on function private.website_state(uuid),private.website_state_v6(uuid) from public,anon,authenticated;grant execute on function private.website_state(uuid),private.website_state_v6(uuid) to service_role;
-- Bulk read verification uses independent leases and never changes publication timing.
do $$ declare d text;begin d:=pg_get_functiondef('public.claim_qualification_check()'::regprocedure);if position('>=3 then return null' in d)=0 then raise exception 'Inspect qualification concurrency guard';end if;execute replace(d,'>=3 then return null','>=16 then return null');end $$;
-- Preserve every observation, but retry temporary failures with durable backoff.
do $$ declare d text;needle text:='update public.qualification_checks set status=''complete'',result=p_result,completed_at=clock_timestamp(),lease_token=null,lease_until=null where id=r.id;';begin d:=pg_get_functiondef('public.finish_qualification_check(uuid,uuid,jsonb)'::regprocedure);if position(needle in d)=0 then raise exception 'Inspect qualification completion guard';end if;
 d:=replace(d,needle,'update public.website_qualifications set discovery_evidence=coalesce(p_result->''discovery'',''{}'') where website_id=w.id; update public.qualification_checks set status=case when reach=''temporarily_unavailable'' and attempts<3 then ''queued'' else ''complete'' end,result=p_result,completed_at=case when reach=''temporarily_unavailable'' and attempts<3 then null else clock_timestamp() end,next_check_at=case when attempts=1 then now()+interval ''60 seconds'' else now()+interval ''5 minutes'' end,lease_token=null,lease_until=null where id=r.id;');execute d;
end $$;
create function public.workbook_report_rows(p_actor uuid,p_workbook uuid,p_offset integer default 0,p_limit integer default 500) returns jsonb language plpgsql stable set search_path='' as $$ declare a public.profiles;b public.workbook_imports;result jsonb;begin
 select * into a from public.profiles where id=p_actor;select * into b from public.workbook_imports where id=p_workbook and tenant_id=a.tenant_id and (owner_id=a.id or private.actor_permission(a.id,'websites.read_all'));if b.id is null or not private.actor_permission(a.id,'websites.create') then raise exception 'Workbook access required';end if;
 select coalesce(jsonb_agg(to_jsonb(r)||jsonb_build_object('qualification',case when r.website_id is null then jsonb_build_object('group','rejected','auto_ready',false,'quality_status','invalid_domain','reason',r.message) when not private.actor_website_access(a.id,r.website_id,'read') then jsonb_build_object('group','pending_verification','auto_ready',false,'reason','Website assignment required to read existing evidence.') else private.website_state(r.website_id) end)),'[]') into result from (select * from public.import_rows where workbook_id=b.id and tenant_id=a.tenant_id order by sequence_number offset greatest(0,p_offset) limit greatest(1,least(500,p_limit))) r;return result;
end $$;
create function public.workbook_verification_summary(p_actor uuid,p_workbook uuid) returns jsonb language plpgsql stable set search_path='' as $$ declare a public.profiles;b public.workbook_imports;states jsonb;counts jsonb;jobs jsonb;begin
 select * into a from public.profiles where id=p_actor;select * into b from public.workbook_imports where id=p_workbook and tenant_id=a.tenant_id and (owner_id=a.id or private.actor_permission(a.id,'websites.read_all'));if b.id is null or not private.actor_permission(a.id,'websites.create') then raise exception 'Workbook access required';end if;
 select jsonb_agg(private.website_state(s.website_id)) into states from (select distinct website_id from public.import_rows where workbook_id=b.id and website_id is not null and private.actor_website_access(a.id,website_id,'read')) s;
 select jsonb_object_agg(status,n) into counts from (select status,count(*) n from public.import_rows where workbook_id=b.id group by status) s;
 select jsonb_object_agg(status,n) into jobs from (select c.status,count(distinct c.website_id) n from public.qualification_checks c join public.import_rows r on r.website_id=c.website_id where r.workbook_id=b.id and c.id=(select x.id from public.qualification_checks x where x.website_id=c.website_id order by created_at desc limit 1) group by c.status) s;
 return jsonb_build_object('workbook',to_jsonb(b),'source',b.source_summary,'row_outcomes',coalesce(counts,'{}'),'latest_checks',coalesce(jobs,'{}'),'groups',(select coalesce(jsonb_object_agg(k,n),'{}') from (select q->>'group' k,count(*) n from jsonb_array_elements(coalesce(states,'[]')) q group by q->>'group') g),'verified_metrics',jsonb_build_object('da_30',(select count(*) from jsonb_array_elements(coalesce(states,'[]')) q where (q->>'domain_authority')::numeric>=30),'dr_30',(select count(*) from jsonb_array_elements(coalesce(states,'[]')) q where (q->>'domain_rating')::numeric>=30),'spam_below_5',(select count(*) from jsonb_array_elements(coalesce(states,'[]')) q where (q->>'spam_score')::numeric<5),'all_three',(select count(*) from jsonb_array_elements(coalesce(states,'[]')) q where (q->>'domain_authority')::numeric>=30 and (q->>'domain_rating')::numeric>=30 and (q->>'spam_score')::numeric<5)),'reachability',(select coalesce(jsonb_object_agg(k,n),'{}') from (select q->>'reachability_status' k,count(*) n from jsonb_array_elements(coalesce(states,'[]')) q group by q->>'reachability_status') g));
end $$;
revoke all on function public.workbook_report_rows(uuid,uuid,integer,integer),public.workbook_verification_summary(uuid,uuid) from public,anon,authenticated;grant execute on function public.workbook_report_rows(uuid,uuid,integer,integer),public.workbook_verification_summary(uuid,uuid) to service_role;

create or replace function public.inventory_readiness(p_actor uuid,p_offset integer default 0,p_limit integer default 500) returns jsonb language sql stable set search_path='' as $$
 select coalesce(jsonb_agg(jsonb_build_object('id',s.id,'qualification',private.website_state(s.id)-'reachability_evidence'-'guidelines_evidence'-'review_notes'-'discovery','can_publish',private.actor_website_access(p_actor,s.id,'publish'),'can_connect',private.actor_website_access(p_actor,s.id,'connect'))),'[]') from (select w.id from public.websites w where private.actor_website_access(p_actor,w.id,'read') and private.actor_permission(p_actor,'websites.read') order by w.created_at,w.id offset greatest(0,p_offset) limit greatest(1,least(500,p_limit))) s
$$;
